#define TFT_MISO 12
#define TFT_MOSI 13
#define TFT_SCLK 14
#define TFT_CS   15
#define TFT_DC    2
#define TFT_RST  -1
#define TFT_BL   21

SPIClass tftSPI(HSPI);
Adafruit_ILI9341 tft(&tftSPI, TFT_DC, TFT_CS, TFT_RST);

// ===== Configuration AP =====
const char* AP_SSID = "MeteoStation-Setup";
const char* AP_PASS = "meteostation"; // minimum 8 chars
IPAddress apIP(192, 168, 0, 1);
IPAddress apGW(192, 168, 0, 1);
IPAddress apMask(255, 255, 255, 0);

DNSServer dnsServer;
WebServer server(80);
Preferences prefs;

String cfgSSID;
String cfgPASS;
String cfgCITY = "Moscow";

float weatherLat = 55.7558;
float weatherLon = 37.6173;
bool coordsValid = false;

float temperatureC = NAN;
float feelsLikeC = NAN;
float humidityPct = NAN;
float windKmh = NAN;
int weatherCode = -1;
String weatherTime = "--:--";
String weatherText = "Waiting for WiFi";
String lastError = "";
unsigned long lastWeatherUpdate = 0;
const unsigned long WEATHER_INTERVAL_MS = 10UL * 60UL * 1000UL;

String htmlEscape(const String &s) {
  String out;
  out.reserve(s.length() + 16);
  for (size_t i = 0; i < s.length(); i++) {
    char c = s[i];
    if (c == '&') out += "&amp;";
    else if (c == '<') out += "&lt;";
    else if (c == '>') out += "&gt;";
    else if (c == '"') out += "&quot;";
    else out += c;
  }
  return out;
}

String urlEncode(const String &s) {
  String out;
  char hex[4];
  for (size_t i = 0; i < s.length(); i++) {
    unsigned char c = (unsigned char)s[i];
    if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
        (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.' || c == '~') {
      out += (char)c;
    } else {
      snprintf(hex, sizeof(hex), "%%%02X", c);
      out += hex;
    }
  }
  return out;
}

String weatherCodeText(int code) {
  if (code == 0) return "Clear";
  if (code == 1) return "Mainly clear";
  if (code == 2) return "Partly cloudy";
  if (code == 3) return "Cloudy";
  if (code == 45 || code == 48) return "Fog";
  if (code == 51 || code == 53 || code == 55) return "Drizzle";
  if (code == 56 || code == 57) return "Freezing drizzle";
  if (code == 61 || code == 63 || code == 65) return "Rain";
  if (code == 66 || code == 67) return "Freezing rain";
  if (code == 71 || code == 73 || code == 75 || code == 77) return "Snow";
  if (code == 80 || code == 81 || code == 82) return "Rain showers";
  if (code == 85 || code == 86) return "Snow showers";
  if (code == 95 || code == 96 || code == 99) return "Thunderstorm";
  return "Unknown";
}

void drawHeader(const String &title) {
  tft.fillScreen(ILI9341_BLACK);
  tft.fillRect(0, 0, 320, 36, ILI9341_DARKCYAN);
  tft.setTextColor(ILI9341_WHITE);
  tft.setTextSize(2);
  tft.setCursor(10, 10);
  tft.print(title);
}

