    tft.setTextColor(ILI9341_WHITE);
    tft.setTextSize(1);
    tft.setCursor(10, 115);
    tft.println("Connect to:");
    tft.setTextSize(2);
    tft.setCursor(10, 132);
    tft.println(AP_SSID);
    tft.setTextSize(1);
    tft.setCursor(10, 164);
    tft.print("Password: "); tft.println(AP_PASS);
    tft.setCursor(10, 184);
    tft.println("Open: http://192.168.0.1");
    return;
  }

  tft.setTextColor(ILI9341_WHITE);
  tft.setTextSize(1);
  tft.setCursor(10, 70);
  tft.print("WiFi: "); tft.print(cfgSSID);
  tft.setCursor(210, 70);
  tft.print("RSSI "); tft.print(WiFi.RSSI());

  if (isnan(temperatureC)) {
    tft.setTextColor(ILI9341_YELLOW);
    tft.setTextSize(2);
    tft.setCursor(10, 105);
    tft.println("Loading weather...");
    if (lastError.length()) {
      tft.setTextColor(ILI9341_RED);
      tft.setTextSize(1);
      tft.setCursor(10, 145);
      tft.println(lastError.substring(0, 48));
