  tft.setTextColor(ILI9341_ORANGE);
  tft.setTextSize(5);
  tft.setCursor(10, 88);
  tft.print(temperatureC, 1);
  tft.setTextSize(2);
  tft.print(" C");

  tft.setTextColor(ILI9341_WHITE);
  tft.setTextSize(2);
  tft.setCursor(10, 145);
  tft.print(weatherText);

  tft.setTextSize(1);
  tft.setCursor(10, 176);
  tft.print("Feels: "); tft.print(feelsLikeC, 1); tft.print(" C");
  tft.setCursor(125, 176);
  tft.print("Humidity: "); tft.print(humidityPct, 0); tft.print("%");
  tft.setCursor(10, 198);
  tft.print("Wind: "); tft.print(windKmh, 1); tft.print(" km/h");
  tft.setCursor(180, 198);
  tft.print(weatherTime);

  tft.setTextColor(ILI9341_GREEN);
  tft.setCursor(10, 224);
  tft.print("Setup AP: 192.168.0.1");
}

bool resolveCity() {
  if (WiFi.status() != WL_CONNECTED) return false;

  WiFiClientSecure client;
  client.setInsecure();
  HTTPClient http;
  String url = "https://geocoding-api.open-meteo.com/v1/search?name=" + urlEncode(cfgCITY) +
               "&count=1&language=en&format=json";
  if (!http.begin(client, url)) {
    lastError = "Geocoding begin failed";
    return false;
  }
  http.setTimeout(12000);
  int code = http.GET();
  if (code != HTTP_CODE_OK) {
    lastError = "Geocoding HTTP " + String(code);
    http.end();
    return false;
  }

  String payload = http.getString();
  http.end();
  JsonDocument doc;
  DeserializationError err = deserializeJson(doc, payload);
  if (err || !doc["results"][0]["latitude"].is<float>()) {
    lastError = "City not found";
    return false;
  }

  weatherLat = doc["results"][0]["latitude"].as<float>();
  weatherLon = doc["results"][0]["longitude"].as<float>();
  coordsValid = true;
  return true;
}

bool updateWeather() {
  // Throttle even failed requests so network errors do not trigger requests every loop.
  lastWeatherUpdate = millis();
  if (WiFi.status() != WL_CONNECTED) return false;
  if (!coordsValid && !resolveCity()) return false;

  WiFiClientSecure client;
  client.setInsecure();
  HTTPClient http;
  String url = "https://api.open-meteo.com/v1/forecast?latitude=" + String(weatherLat, 5) +
               "&longitude=" + String(weatherLon, 5) +
               "&current=temperature_2m,apparent_temperature,relative_humidity_2m,weather_code,wind_speed_10m"
               "&wind_speed_unit=kmh&timezone=auto";

  if (!http.begin(client, url)) {
    lastError = "Weather begin failed";
    return false;
  }
  http.setTimeout(12000);
  int code = http.GET();
  if (code != HTTP_CODE_OK) {
    lastError = "Weather HTTP " + String(code);
    http.end();
    return false;
  }

  String payload = http.getString();
  http.end();
  JsonDocument doc;
  DeserializationError err = deserializeJson(doc, payload);
  if (err) {
    lastError = "Weather JSON error";
    return false;
  }

  JsonObject cur = doc["current"];
  temperatureC = cur["temperature_2m"] | NAN;
  feelsLikeC = cur["apparent_temperature"] | NAN;
  humidityPct = cur["relative_humidity_2m"] | NAN;
  windKmh = cur["wind_speed_10m"] | NAN;
  weatherCode = cur["weather_code"] | -1;
  String iso = cur["time"] | "";
  weatherTime = iso.length() >= 16 ? iso.substring(11, 16) : "--:--";
  weatherText = weatherCodeText(weatherCode);
  lastError = "";
  lastWeatherUpdate = millis();
  drawStatus();
  return true;
}

