    options += "<option value=\"" + htmlEscape(ssid) + "\"";
    if (ssid == cfgSSID) options += " selected";
    options += ">" + htmlEscape(ssid) + " (" + String(WiFi.RSSI(i)) + " dBm)</option>";
  }
  WiFi.scanDelete();

  String status = WiFi.status() == WL_CONNECTED
      ? ("Подключено к <b>" + htmlEscape(WiFi.SSID()) + "</b>, IP: " + WiFi.localIP().toString())
      : "Домашний Wi-Fi пока не подключён";

  String page = R"HTML(
<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Mini Meteo Station</title><style>
body{font-family:system-ui,Arial;background:#0d1117;color:#e6edf3;margin:0;padding:20px}.card{max-width:620px;margin:auto;background:#161b22;border:1px solid #30363d;border-radius:16px;padding:20px}h1{font-size:24px;margin:0 0 8px}.muted{color:#8b949e}label{display:block;margin-top:14px;margin-bottom:6px}select,input{width:100%;box-sizing:border-box;padding:12px;border-radius:10px;border:1px solid #30363d;background:#0d1117;color:white;font-size:16px}button{width:100%;margin-top:18px;padding:13px;border:0;border-radius:10px;background:#238636;color:white;font-size:16px;font-weight:700}.weather{margin-top:18px;padding:14px;border-radius:12px;background:#0d1117}.ok{color:#3fb950}.small{font-size:13px}</style></head><body><div class="card">
<h1>Мини-метеостанция ESP32</h1><div class="muted">Тестовая прошивка для ESP32-2432S028</div><p>)HTML";
  page += status;
  page += R"HTML(</p><form method="POST" action="/save">
<label>Домашняя сеть Wi‑Fi</label><select name="ssid">)HTML" + options + R"HTML(</select>
<label>Пароль Wi‑Fi</label><input type="password" name="pass" placeholder="Оставьте пустым, если пароль не меняется">
<label>Город для погоды</label><input name="city" value=")HTML" + htmlEscape(cfgCITY) + R"HTML(" placeholder="Например: Moscow, Kazan, Sochi">
<button type="submit">Сохранить и подключиться</button></form>
<div class="weather"><b>Погода сейчас:</b><br>)HTML";
  if (isnan(temperatureC)) page += "Данных пока нет";
  else page += String(temperatureC, 1) + " °C, " + htmlEscape(weatherText) + ", влажность " + String(humidityPct, 0) + "%";
  page += R"HTML(</div><p class="small muted">Точка доступа: MeteoStation-Setup · адрес настройки: 192.168.0.1</p>
</div></body></html>)HTML";
  return page;
}

void redirectToPortal() {
  server.sendHeader("Location", "http://192.168.0.1/", true);
  server.send(302, "text/plain", "");
}

void setupWeb() {
  server.on("/", HTTP_GET, []() { server.send(200, "text/html; charset=utf-8", buildPage()); });
  server.on("/save", HTTP_POST, []() {
    String newSSID = server.arg("ssid");
    String newPASS = server.arg("pass");
    String newCITY = server.arg("city");
    newSSID.trim(); newCITY.trim();
    if (newCITY.length() == 0) newCITY = "Moscow";

    if (newSSID.length()) {
      cfgSSID = newSSID;
      prefs.putString("ssid", cfgSSID);
      if (newPASS.length()) {
        cfgPASS = newPASS;
        prefs.putString("pass", cfgPASS);
      }
    }
    cfgCITY = newCITY;
    prefs.putString("city", cfgCITY);
    coordsValid = false;

    server.send(200, "text/html; charset=utf-8",
      "<!doctype html><meta charset='utf-8'><style>body{font-family:system-ui;background:#0d1117;color:white;padding:30px}</style>"
      "<h2>Сохранено</h2><p>ESP32 перезапускается и пробует подключиться к Wi‑Fi.</p><p>Через несколько секунд снова откройте <b>192.168.0.1</b>.</p>");
    delay(1000);
    ESP.restart();
  });

  server.on("/generate_204", HTTP_ANY, redirectToPortal);
  server.on("/gen_204", HTTP_ANY, redirectToPortal);
  server.on("/hotspot-detect.html", HTTP_ANY, redirectToPortal);
  server.on("/library/test/success.html", HTTP_ANY, redirectToPortal);
  server.on("/ncsi.txt", HTTP_ANY, redirectToPortal);
  server.onNotFound(redirectToPortal);
  server.begin();
}

void connectWiFi() {
  WiFi.mode(WIFI_AP_STA);
  WiFi.softAPConfig(apIP, apGW, apMask);
  WiFi.softAP(AP_SSID, AP_PASS);
  dnsServer.start(53, "*", apIP);

  if (cfgSSID.length() == 0) return;
  WiFi.begin(cfgSSID.c_str(), cfgPASS.c_str());
  unsigned long start = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - start < 15000) {
    delay(250);
  }
}

void setup() {
  Serial.begin(115200);

  pinMode(TFT_BL, OUTPUT);
  digitalWrite(TFT_BL, HIGH);
  tftSPI.begin(TFT_SCLK, TFT_MISO, TFT_MOSI, TFT_CS);
  tft.begin();
  tft.setRotation(1);

  prefs.begin("meteo", false);
  cfgSSID = prefs.getString("ssid", "");
  cfgPASS = prefs.getString("pass", "");
  cfgCITY = prefs.getString("city", "Moscow");

  drawHeader("MINI METEO STATION");
  tft.setTextColor(ILI9341_WHITE);
  tft.setTextSize(2);
  tft.setCursor(10, 70);
  tft.println("Starting WiFi...");

  connectWiFi();
  setupWeb();
  drawStatus();

  if (WiFi.status() == WL_CONNECTED) {
    updateWeather();
  }
}

void loop() {
  dnsServer.processNextRequest();
  server.handleClient();

  static wl_status_t lastStatus = WL_IDLE_STATUS;
  wl_status_t now = WiFi.status();
  if (now != lastStatus) {
    lastStatus = now;
    drawStatus();
  }

  if (now == WL_CONNECTED) {
    if (lastWeatherUpdate == 0 || millis() - lastWeatherUpdate >= WEATHER_INTERVAL_MS) {
      updateWeather();
    }
  }
  delay(5);
}
